import{_ as a,o as s,c as i,a2 as l}from"./chunks/framework.C4u7U0Dw.js";const c=JSON.parse('{"title":"第 4 章 快速完成第一个真实任务","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第一篇 使用手册：先把我用起来/第 4 章 快速完成第一个真实任务.md","filePath":"bluebook/第一篇 使用手册：先把我用起来/第 4 章 快速完成第一个真实任务.md"}'),o={name:"bluebook/第一篇 使用手册：先把我用起来/第 4 章 快速完成第一个真实任务.md"};function e(d,t,n,r,h,p){return s(),i("div",null,[...t[0]||(t[0]=[l(`<div class="tip custom-block"><p class="custom-block-title">🎈 想读易懂版？</p><p>本章有<strong>易懂版</strong>（大白话讲重点，10 分钟读完）：[第 4 章 快速完成第一个真实任务（易懂版）](../../easy/第4章 快速完成第一个真实任务（易懂版）.md)</p></div><h1 id="第-4-章-快速完成第一个真实任务" tabindex="-1">第 4 章 快速完成第一个真实任务 <a class="header-anchor" href="#第-4-章-快速完成第一个真实任务" aria-label="Permalink to &quot;第 4 章 快速完成第一个真实任务&quot;">​</a></h1><blockquote><p>本章目标：跑通你的第一个真实任务闭环。从选任务、下发任务、盯住关键节点，到失败时的纠偏和完成后的档案沉淀——<strong>一个真实任务跑通，胜过读十篇教程</strong>。</p></blockquote><h2 id="_4-1-为什么必须是-真实任务" tabindex="-1">4.1 为什么必须是&quot;真实任务&quot; <a class="header-anchor" href="#_4-1-为什么必须是-真实任务" aria-label="Permalink to &quot;4.1 为什么必须是&quot;真实任务&quot;&quot;">​</a></h2><p>教程里的示例任务（&quot;帮我写个 hello world&quot;）没有价值，因为它没有验收标准。<strong>真实任务才有摩擦</strong>：有格式要求、有历史包袱、有你的审美。第一次通过真实任务认识我，你才知道我是不是真的能帮上忙。</p><h3 id="_4-1-1-示例任务-vs-真实任务" tabindex="-1">4.1.1 示例任务 vs 真实任务 <a class="header-anchor" href="#_4-1-1-示例任务-vs-真实任务" aria-label="Permalink to &quot;4.1.1 示例任务 vs 真实任务&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>示例任务</th><th>真实任务</th></tr></thead><tbody><tr><td>验收标准</td><td>没有，随便跑通即可</td><td>明确（格式、口径、质量）</td></tr><tr><td>摩擦点</td><td>无</td><td>格式要求、历史数据、你的审美</td></tr><tr><td>学习价值</td><td>低——没有真实约束</td><td>高——暴露真实问题</td></tr><tr><td>是否可复用</td><td>不可复用</td><td>沉淀为模板/Skill</td></tr></tbody></table><h2 id="_4-2-第一步-选一个合适的任务" tabindex="-1">4.2 第一步：选一个合适的任务 <a class="header-anchor" href="#_4-2-第一步-选一个合适的任务" aria-label="Permalink to &quot;4.2 第一步：选一个合适的任务&quot;">​</a></h2><h3 id="_4-2-1-任务选择标准" tabindex="-1">4.2.1 任务选择标准 <a class="header-anchor" href="#_4-2-1-任务选择标准" aria-label="Permalink to &quot;4.2.1 任务选择标准&quot;">​</a></h3><ul><li>你最近<strong>真的要做的事</strong>（报告、脚本、整理、分析都行）；</li><li>耗时 <strong>10～60 分钟</strong>的小任务，别上来就挑战大项目；</li><li>结果<strong>可检查</strong>（有文件产出、有运行结果）；</li><li>有一定重复性更好（后面可以沉淀为 Skill）。</li></ul><h3 id="_4-2-2-不合适作为第一个任务的" tabindex="-1">4.2.2 不合适作为第一个任务的 <a class="header-anchor" href="#_4-2-2-不合适作为第一个任务的" aria-label="Permalink to &quot;4.2.2 不合适作为第一个任务的&quot;">​</a></h3><ul><li>❌ 涉及机密数据的任务（先建立信任再逐步升级权限）；</li><li>❌ 不可逆操作（删除、覆盖、推送远程仓库）；</li><li>❌ 依赖你实时拍板的大项目（先跑通小闭环）。</li></ul><div class="tip custom-block"><p class="custom-block-title">选择建议</p><p><strong>选一个&quot;做错了损失也不大&quot;的任务。</strong> 第一次合作的核心目的是建立信任，不是创造奇迹。信任建立后，什么都能干。</p></div><h2 id="_4-3-第二步-用四要素下发任务" tabindex="-1">4.3 第二步：用四要素下发任务 <a class="header-anchor" href="#_4-3-第二步-用四要素下发任务" aria-label="Permalink to &quot;4.3 第二步：用四要素下发任务&quot;">​</a></h2><p>套用第 2 章的四要素模板，越具体越好：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>任务：</span></span>
<span class="line"><span>目标：把 data/ 里的 3 个 CSV 合并成一个，并生成汇总表</span></span>
<span class="line"><span>输入：data/ 目录，文件格式见 data/README.md</span></span>
<span class="line"><span>约束：输出合并.xlsx，保留表头，数值取两位小数</span></span>
<span class="line"><span>验收：文件能打开，行数 = 3 文件行数之和</span></span></code></pre></div><h3 id="_4-3-1-为什么-验收-这一条最重要" tabindex="-1">4.3.1 为什么&quot;验收&quot;这一条最重要 <a class="header-anchor" href="#_4-3-1-为什么-验收-这一条最重要" aria-label="Permalink to &quot;4.3.1 为什么&quot;验收&quot;这一条最重要&quot;">​</a></h3><p>没有验收标准，你只能等交付后凭感觉检查；有了验收标准：</p><ul><li><strong>我</strong>有了自检清单，交付前先自查；</li><li><strong>你</strong>有了检查清单，验收时逐条核对；</li><li>万一出错，能精确指出&quot;第几条没满足&quot;，而不是笼统说&quot;不对&quot;。</li></ul><h2 id="_4-4-第三步-标准执行闭环" tabindex="-1">4.4 第三步：标准执行闭环 <a class="header-anchor" href="#_4-4-第三步-标准执行闭环" aria-label="Permalink to &quot;4.4 第三步：标准执行闭环&quot;">​</a></h2><p>无论任务是什么，我都会走这个闭环：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>理解 → 确认 → 执行 → 展示中间产物 → 交付 → 复盘</span></span></code></pre></div><h3 id="_4-4-1-你要盯住的两个节点" tabindex="-1">4.4.1 你要盯住的两个节点 <a class="header-anchor" href="#_4-4-1-你要盯住的两个节点" aria-label="Permalink to &quot;4.4.1 你要盯住的两个节点&quot;">​</a></h3><table tabindex="0"><thead><tr><th>节点</th><th>时间点</th><th>你要做的事</th><th>不做的后果</th></tr></thead><tbody><tr><td><strong>确认节点</strong></td><td>我说&quot;我的理解是……&quot;时</td><td>对齐一次，有偏差立即纠正</td><td>我一路错到底</td></tr><tr><td><strong>验收节点</strong></td><td>交付后</td><td>按你的验收标准逐条检查</td><td>错误悄悄混进产物</td></tr></tbody></table><h3 id="_4-4-2-每个环节的产物" tabindex="-1">4.4.2 每个环节的产物 <a class="header-anchor" href="#_4-4-2-每个环节的产物" aria-label="Permalink to &quot;4.4.2 每个环节的产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>环节</th><th>你应该看到的产物</th><th>检查点</th></tr></thead><tbody><tr><td>理解</td><td>复述任务的话</td><td>理解是否准确</td></tr><tr><td>确认</td><td>对遗漏信息的提问</td><td>有没有问关键问题</td></tr><tr><td>执行</td><td>中间文件、步骤日志</td><td>是否按计划推进</td></tr><tr><td>交付</td><td>最终文件 + 执行说明</td><td>验收标准是否满足</td></tr></tbody></table><h2 id="_4-5-第四步-如果任务失败-跑偏了" tabindex="-1">4.5 第四步：如果任务失败/跑偏了 <a class="header-anchor" href="#_4-5-第四步-如果任务失败-跑偏了" aria-label="Permalink to &quot;4.5 第四步：如果任务失败/跑偏了&quot;">​</a></h2><p>失败不可怕，可怕的是<strong>失败后没有反馈信号</strong>。遇到问题按以下顺序处理：</p><h3 id="_4-5-1-纠偏四连招" tabindex="-1">4.5.1 纠偏四连招 <a class="header-anchor" href="#_4-5-1-纠偏四连招" aria-label="Permalink to &quot;4.5.1 纠偏四连招&quot;">​</a></h3><ol><li><strong>及时叫停</strong>：&quot;停，这里不对。&quot; —— 不要让我继续错下去；</li><li><strong>给出反馈</strong>：&quot;不是要 B，是要 A，区别在于……&quot; —— 具体说清差异；</li><li><strong>缩小范围</strong>：&quot;先只处理 1 个文件试试。&quot; —— 降低单次风险；</li><li><strong>要求中间产物</strong>：&quot;先给我看前 10 行处理结果。&quot; —— 把大任务切成可检查的小步。</li></ol><h3 id="_4-5-2-常见失败模式与对策" tabindex="-1">4.5.2 常见失败模式与对策 <a class="header-anchor" href="#_4-5-2-常见失败模式与对策" aria-label="Permalink to &quot;4.5.2 常见失败模式与对策&quot;">​</a></h3><table tabindex="0"><thead><tr><th>失败模式</th><th>典型信号</th><th>对策</th></tr></thead><tbody><tr><td>理解偏差</td><td>交付物方向不对</td><td>回到确认节点，重新对齐</td></tr><tr><td>数据口径错</td><td>数字对不上</td><td>明确统计规则、时间范围</td></tr><tr><td>范围蔓延</td><td>做着做着加了新需求</td><td>冻结需求，先完成原任务</td></tr><tr><td>工具受限</td><td>权限/网络不足</td><td>换路径或提供必要资源</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">心态建议</p><p><strong>把失败当成调试，而不是事故。</strong> 每一次纠偏都是一次&quot;训练数据的标注&quot;——你告诉我哪里不对，下次我就记住了（配合第 6 章记忆系统，效果更佳）。</p></div><h2 id="_4-6-第五步-留下一份-任务档案" tabindex="-1">4.6 第五步：留下一份&quot;任务档案&quot; <a class="header-anchor" href="#_4-6-第五步-留下一份-任务档案" aria-label="Permalink to &quot;4.6 第五步：留下一份&quot;任务档案&quot;&quot;">​</a></h2><p>任务做完，花两分钟记录档案。这份档案，就是第 17 章&quot;打造 Skill&quot;的原材料：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 任务档案：合并 CSV</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 任务描述：合并 data/ 下 3 个 CSV 并生成汇总</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 成功路径：读 README → 理解格式 → 写脚本 → 验证行数</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 踩坑记录：CSV 编码是 GBK，需转 UTF-8</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 可复用资产：scripts/merge_csv.py + 一句话指令</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 下次优化：加参数支持任意文件数</span></span></code></pre></div><h3 id="_4-6-1-档案的价值" tabindex="-1">4.6.1 档案的价值 <a class="header-anchor" href="#_4-6-1-档案的价值" aria-label="Permalink to &quot;4.6.1 档案的价值&quot;">​</a></h3><ul><li><strong>对你</strong>：以后再遇到同类任务，直接复用，不用重讲；</li><li><strong>对我</strong>：理解了你的业务与偏好，越用越顺；</li><li><strong>对团队</strong>：沉淀为公共 Skill，全团队受益（见第 16、17 章）。</li></ul><h2 id="_4-7-本章练习" tabindex="-1">4.7 本章练习 <a class="header-anchor" href="#_4-7-本章练习" aria-label="Permalink to &quot;4.7 本章练习&quot;">​</a></h2><ol><li>挑一个你本周要做的小任务，用四要素模板发给我。</li><li>盯住确认节点和验收节点，跑完一次完整闭环。</li><li>记录任务档案，存到项目的 memory 或 docs 里。</li><li>回顾：这次协作哪里最顺？哪里最卡？把答案写进档案，作为下次优化的依据。</li></ol><hr><blockquote><p>小结：<strong>第一个真实任务跑通，比读十篇教程都值钱。</strong> 因为从此刻起，你拥有了&quot;AI 能帮我干活&quot;的第一手经验。有了这个闭环经验，下一章我们学习如何让经验复用——Skill。</p></blockquote>`,42)])])}const b=a(o,[["render",e]]);export{c as __pageData,b as default};
